func rid11TokenCase(id string) bool { r, ok := rid11PublicRules[id]; return ok && r.Token401 }
func rid11PublicCaseID(c rid11Case, stage string) string {
	state := "ABSENT"
	if c.Active {
		state = "ACTIVE"
	}
	kind := "NEGATIVE"
	if c.Twin {
		kind = "TWIN"
	}
	return "registry-installation-rid11-" + strings.ToUpper(c.Variant) + "-" + c.Mode + "-" + state + "-" + kind + "-" + stage
}
